const incoming = $input.first().json;
const r = incoming.body && typeof incoming.body === 'object' ? incoming.body : incoming;
const first = (...names) => { for (const name of names) { const value = r[name]; if (value !== undefined && value !== null && value !== '') return value; } };
const text = value => { if (Array.isArray(value)) value = value[0]; if (value && typeof value === 'object') value = value.name ?? value.value ?? value.id; return value === undefined || value === null ? '' : String(value).trim(); };
const recordId = text(first('recordId', 'Record ID', 'Airtable Record ID'));
const action = text(first('Bison Action', 'Campaign Action'));
const campaignId = text(first('ID', 'EmailBison Generic Campaign ID', 'EmailBison Direct Campaign ID', 'EmailBison Campaign ID', 'Bison Campaign ID'));
const apiKey = text(first('EmailBison API (from Client)', 'EmailBison API', 'Bison API Key'));
const baseUrl = text(first('EmailBison Base URL', 'Bison Base URL')) || 'https://send.dulcy.io';
if (!recordId || !recordId.startsWith('rec')) throw new Error('A valid Airtable Campaign recordId is required.');
if (!['Launch','Pause','Delete'].includes(action)) throw new Error('Bison Action must be Launch, Pause, or Delete.');
if (action !== 'Delete' && !campaignId) throw new Error('This campaign has no EmailBison campaign ID yet. Create the EmailBison draft before launching or pausing it.');
if (campaignId && !apiKey) throw new Error('EmailBison API (from Client) is missing.');
return [{json: {recordId, action, campaignId, apiKey, baseUrl}}];

